#!/usr/bin/env node
// Rebuilds docs/training/assets/search-index.js from the guide's HTML pages.
// Run after adding or renaming a page or a heading:
//   node docs/training/tools/build-search-index.mjs
// The guide stays build-free: the generated file is committed, and pages load it with a
// plain <script> tag so search works when the site is opened from disk.
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const TRACKS = {
  '.': 'Start',
  operators: 'Operators',
  staff: 'Staff',
  testing: 'Testers',
  reference: 'Reference',
};

async function htmlFiles(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const full = join(dir, entry.name);
    if (entry.isDirectory() && entry.name !== 'assets' && entry.name !== 'tools') {
      files.push(...(await htmlFiles(full)));
    } else if (entry.isFile() && entry.name.endsWith('.html')) {
      files.push(full);
    }
  }
  return files;
}

function text(html) {
  return html
    .replace(/<[^>]+>/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const pages = [];
for (const file of (await htmlFiles(root)).sort()) {
  const html = await readFile(file, 'utf8');
  const url = relative(root, file).split(sep).join('/');
  const folder = url.includes('/') ? url.split('/')[0] : '.';
  const h1 = /<h1[^>]*>([\s\S]*?)<\/h1>/.exec(html);
  const title = h1 ? text(h1[1]) : url;
  const sections = [];
  for (const match of html.matchAll(/<h([23])[^>]*\sid="([^"]+)"[^>]*>([\s\S]*?)<\/h\1>/g)) {
    sections.push([match[2], text(match[3])]);
  }
  const lede = /<p class="lede[^"]*">([\s\S]*?)<\/p>/.exec(html);
  const codes = [...html.matchAll(/<code>([^<]{3,60})<\/code>/g)].map((m) => text(m[1]));
  const keywords = [lede ? text(lede[1]) : '', ...new Set(codes)].join(' ').slice(0, 1200);
  pages.push({ title, url, track: TRACKS[folder] ?? 'Guide', keywords, sections });
}

const banner =
  '/* Generated by docs/training/tools/build-search-index.mjs. Do not edit by hand. */\n';
await writeFile(
  join(root, 'assets', 'search-index.js'),
  `${banner}window.TAXDESK_GUIDE_INDEX = ${JSON.stringify(pages, null, 1)};\n`,
);
console.log(`search index: ${pages.length} pages, ${pages.reduce((n, p) => n + p.sections.length, 0)} sections`);
